import type { BiomarkerInput, DrugInput, EntityInput, PaperInput, PathwayInput, TargetInput, TechnologyInput, TermInput, TrialInput } from "@/lib/schema";
import type { Spike, SpikeSupplement } from "./index";

/**
 * PANCREATIC DUCTAL ADENOCARCINOMA, MOLECULAR LAYER. Facts checked 2026-09-24.
 *
 * The genomic landscape as a sourced table (`pancreaticMolecularLandscape`), the transcriptional subtypes (Collisson,
 * Moffitt, Bailey, COMPASS) with what each has been shown to mean for chemotherapy, the precursor lesion sequence
 * (PanIN, IPMN, MCN) with the driver order and its revisions, the stroma and immune microenvironment as the published
 * reason checkpoint blockade fails outside mismatch repair deficiency, CA 19-9 and ctDNA as monitoring markers with
 * their limits, the early detection programmes (CAPS, PRECEDE, blood tests) marked as research, and the biomarker
 * readouts, targets, tests and RAS inhibitors that follow from it; and paper records for every landscape paper cited.
 *
 * Sources and rules. Every frequency names its cohort, its size and the paper it was read from. Figures marked
 * "cBioPortal" were computed on 24 Sept 2026 from the public cBioPortal API (read-only) on the named study id: the
 * count of samples carrying a non-synonymous mutation (or a high-level amplification / deep deletion in the discrete
 * copy-number profile, or a structural variant) over the study's sequenced sample list. They are sample-level
 * frequencies for the study as deposited, not the paper's own percentages, which are quoted alongside where an abstract
 * gives them. KRAS allele shares are counts of mutation records over all KRAS mutation records in the study, so a tumour
 * with two KRAS mutations is counted twice. The TCGA deposit (184 samples) includes the low-cellularity and
 * non-ductal samples the 2017 paper excluded from its 150-tumour analysis, which is why its KRAS rate reads low; the
 * purified or microdissected cohorts (UTSW, MSK, CPTAC) read 92 to 96%. Nothing is invented and no OncoKB or COSMIC data
 * was used. Abstract text was read from Europe PMC.
 *
 * Cancer id. The corpus cancer record is `pancreatic` (src/data/cancers.ts, patched by spikes/pancreatic.ts, with the
 * stage and molecular children in pancreatic-subtypes.ts); this file patches it. Every reference goes through
 * PANCREATIC_CANCER_ID.
 *
 * Terms and trials are not created here (the owner's brief for this layer); the report lists the ones the layer would
 * link to (PanIN, IPMN, MCN, Lewis antigen status, GATA6, classical and basal-like subtypes, CAF subtypes, KRAS
 * allelic imbalance, COMPASS, CAPS, Know Your Tumor, CodeBreaK 100, KRYSTAL-1, HALO-301, DETECT-A, CCGA).
 */
export const PANCREATIC_CANCER_ID = "pancreatic";
const PC = PANCREATIC_CANCER_ID;
const asOf = "2026-09-24";

const doi = (d: string) => `https://doi.org/${d}`;
const pubmed = (pmid: string) => `https://pubmed.ncbi.nlm.nih.gov/${pmid}/`;
const cbio = (study: string) => `https://www.cbioportal.org/study/summary?id=${study}`;

type P = Omit<PaperInput, "kind" | "asOf">;
const p = (x: P): PaperInput => ({ kind: "paper", asOf, ...x });
/** A partial record for an entity another file owns; arrays append, scalars fill gaps only (see applySpikeSupplements). */
const sup = <T extends EntityInput>(x: { id: string } & Partial<Omit<T, "id" | "kind">>): SpikeSupplement => x as SpikeSupplement;

