const landscapeTargetRows = pancreaticMolecularLandscape.filter((r): r is PancreaticLandscapeRow & { targetId: string } => !!r.targetId);

// ======================= SUBTYPES, PRECURSORS, MICROENVIRONMENT, MONITORING, EARLY DETECTION =======================
export const pancreaticSubtypes: Array<{ scheme: string; subtype: string; share: string; biology: string; therapy: string; sources: Array<{ label: string; url: string }> }> = [
  { scheme: "Collisson (2011)", subtype: "Classical, quasi-mesenchymal (QM-PDA), exocrine-like", share: "Three subtypes from combined transcriptional profiles of primary tumours and human and mouse cell lines (Collisson 2011); the exocrine-like class was later shown to reflect acinar contamination (Puleo 2018)",
    biology: "Classical tumours express epithelial and GATA6-associated programmes; quasi-mesenchymal tumours express mesenchymal genes and carry the worse outcome (Collisson 2011).",
    therapy: "The paper presents evidence for clinical outcome and therapeutic response differences between subtypes in cell-line models; it is the first published claim that pancreatic cancer subtypes should stratify treatment (Collisson 2011).",
    sources: [link(SRC.collisson2011), link(SRC.puleo2018)] },
  { scheme: "Moffitt (2015)", subtype: "Basal-like versus classical tumour; normal versus activated stroma", share: "Two tumour subtypes and two independently prognostic stromal subtypes from virtual microdissection of microarray data (Moffitt 2015); basal-like 39 of 195 advanced COMPASS patients, 20% (O'Kane 2020)",
    biology: "Basal-like tumours are molecularly similar to basal bladder and breast cancers and have worse outcome; activated stroma is independently prognostic (Moffitt 2015). Squamous histology is the tissue correlate of basal-like expression and often a subclone within a classical tumour, with clonal chromatin-modifier mutations and MYC amplification heterogeneity (Hayashi 2020). Subtypes form a continuum driven by mutant KRAS and GATA6 copy number, with tetraploidisation behind the events (Chan-Seng-Yue 2020).",
    therapy: "In COMPASS, response to first-line chemotherapy was 10% in basal-like against 33% in classical tumours; 60% of basal-like patients progressed on modified FOLFIRINOX against 15% of classical; median overall survival 5.9 against 9.3 months (hazard ratio 0.47) (O'Kane 2020; Aung 2018). The PurIST single-sample classifier reproduces the two-subtype schema on biopsies and carries FOLFIRINOX response implications (Rashid 2020). About 12% of tumours are subtype-discordant hybrids with intermediate survival (Topham 2021).",
    sources: [link(SRC.moffitt2015), link(SRC.okane2020), link(SRC.aung2018), link(SRC.hayashi2020), link(SRC.chanSengYue2020), link(SRC.rashid2020), link(SRC.topham2021)] },
  { scheme: "Bailey (2016, QCMG)", subtype: "Squamous, pancreatic progenitor, immunogenic, ADEX", share: "Four expression subtypes among 456 cancers (96 with RNA sequencing) (Bailey 2016); ADEX reproduces the exocrine-like signal of acinar contamination (Puleo 2018)",
    biology: "Squamous tumours are enriched for TP53 and KDM6A mutation, TP63 delta-N network activation and hypermethylation of pancreatic endodermal fate genes, and carry a poor prognosis; progenitor tumours express FOXA2/3, PDX1 and MNX1; immunogenic tumours carry upregulated immune networks including acquired immune suppression (Bailey 2016). KDM6A loss recreates the squamous programme in mice and confers BET-inhibitor sensitivity (Andricovich 2018).",
    therapy: "No prospective subtype-directed trial has changed a guideline; the squamous and basal-like classes overlap and share the chemotherapy resistance shown in COMPASS (O'Kane 2020).",
    sources: [link(SRC.bailey2016), link(SRC.puleo2018), link(SRC.andricovich2018), link(SRC.okane2020)] },
  { scheme: "Puleo (2018, formalin-fixed tissue)", subtype: "Pure basal-like, stroma activated, desmoplastic, pure classical, immune classical", share: "Five subtypes from 309 consecutive resections after removing normal contamination, validated in TCGA and ICGC (Puleo 2018)",
    biology: "Adds the microenvironment to the tumour-intrinsic split: the immune classical and desmoplastic classes carry immune and stromal programmes that could be targeted (Puleo 2018). Spatially, reactive sub-tumour microenvironments are immune-hot with aggressive tumour phenotypes and deserted, matrix-rich ones are chemoprotective and enriched after chemotherapy (Grunwald 2021).",
    therapy: "Proposed for treatment selection; not yet tested prospectively (Puleo 2018).",
    sources: [link(SRC.puleo2018), link(SRC.grunwald2021)] },
  { scheme: "Structural variation (Waddell 2015)", subtype: "Stable, locally rearranged, scattered, unstable", share: "Four genome-rearrangement subtypes among 100 whole genomes (Waddell 2015)",
    biology: "Unstable genomes co-segregate with BRCA1, BRCA2 or PALB2 inactivation and a DNA-damage repair mutational signature (Waddell 2015); mutational signatures cluster into age-related, double-strand break repair, mismatch repair and signature-8 subtypes, the repair-defective ones carrying more neoantigens and cytotoxic T-cell expression (Connor 2017).",
    therapy: "Of 8 platinum-treated patients, 4 of 5 with defective DNA maintenance responded (Waddell 2015); first-line platinum gave a progression-free survival hazard ratio of 0.44 in the 19% with homologous recombination gene mutations (Park 2020).",
    sources: [link(SRC.waddell2015), link(SRC.connor2017), link(SRC.park2020)] },
];

export const pancreaticPrecursors: Array<{ lesion: string; drivers: string; sequence: string; sources: Array<{ label: string; url: string }> }> = [
  { lesion: "Pancreatic intraepithelial neoplasia (PanIN)", drivers: "KRAS, CDKN2A, GNAS or BRAF mutations in more than 99% of the earliest, lowest-grade PanIN-1 lesions (Kanda 2012); the PanIN nomenclature was fixed in 2001 (Hruban 2001) and collapsed to a two-tier low-grade versus high-grade system in 2015, with PanIN of any grade at a resection margin carrying no prognostic weight (Basturk 2015).",
    sequence: "The classical order (KRAS, then CDKN2A, then TP53 and SMAD4) is challenged: two-thirds of tumour genomes carry complex rearrangement patterns from mitotic errors, in some cases knocking out several drivers at once, consistent with punctuated rather than gradual evolution (Notta 2016). Precursor cells clonally expand and move through the ductal system over many years before invasion (Makohon-Moore 2018). At least a decade separates the initiating mutation from the parental non-metastatic clone, at least five more years pass before metastatic ability, and patients die about two years later (Yachida 2010); the drivers are identical across every metastasis of a patient (Makohon-Moore 2017).",
    sources: [link(SRC.kanda2012), link(SRC.hruban2001), link(SRC.basturk2015), link(SRC.notta2016), link(SRC.makohonMoore2018), link(SRC.yachida2010), link(SRC.makohonMoore2017)] },
  { lesion: "Intraductal papillary mucinous neoplasm (IPMN)", drivers: "GNAS codon 201 mutation in 66% of 132 IPMNs, KRAS or GNAS in 96%, carried into the invasive cancer in 7 of 8 associated carcinomas (Wu 2011); RNF43 in 6 of 8 IPMN exomes (Wu 2011, PNAS); SMAD4 and TGFBR2 mutations largely restricted to the invasive component and RNF43 to the non-invasive one, with an average window of over three years between high-grade dysplasia and cancer (Noe 2020). IPMN-associated cancers more often carry FGF23, CCND2, PIK3CA and FGF6 alterations (Singhi 2019).",
    sequence: "Three pathways from IPMN to cancer among 30 pancreata: sequential (all drivers shared, frequent GNAS), branch-off (same KRAS, different GNAS, later divergence) and de novo (no shared drivers) (Omori 2019). Of 61 co-occurring IPMN and ductal cancers, 51% were likely related and 18% likely independent, while every colloid carcinoma was related to its IPMN (Felsenstein 2018). Cyst-fluid molecular markers with clinical features classified cyst type with 90 to 100% sensitivity and could have avoided 91% of unnecessary operations among 130 resected cysts (Springer 2015).",
    sources: [link(SRC.wu2011gnas), link(SRC.wu2011rnf43), link(SRC.noe2020), link(SRC.singhi2019), link(SRC.omori2019), link(SRC.felsenstein2018), link(SRC.springer2015)] },
  { lesion: "Mucinous cystic neoplasm (MCN)", drivers: "KRAS with RNF43 in 3 of 8 MCN exomes and no GNAS, the ovarian-type stroma distinguishing it from IPMN (Wu 2011, PNAS; Basturk 2015).",
    sequence: "MCNs are direct precursors: evolutionary analysis of 148 samples from 18 patients established both IPMNs and MCNs as origins of invasive cancer (Noe 2020). Simple mucinous cysts over 1 cm without ovarian stroma are named separately (Basturk 2015).",
    sources: [link(SRC.wu2011rnf43), link(SRC.basturk2015), link(SRC.noe2020)] },
];

export const pancreaticMicroenvironment: Array<{ feature: string; finding: string; implication: string; sources: Array<{ label: string; url: string }> }> = [
  { feature: "Desmoplastic stroma and drug delivery", finding: "Tumours in the KPC mouse model were poorly perfused and poorly vascularised, as in human disease; depleting stroma through hedgehog inhibition transiently raised intratumoural gemcitabine and stabilised disease (Olive 2009).",
    implication: "Stroma depletion failed clinically and was harmful in mice: deleting alpha-SMA myofibroblasts gave undifferentiated, hypoxic tumours with more regulatory T cells and shorter survival, and fewer myofibroblasts correlated with worse survival in patients (Ozdemir 2014); Shh deletion or smoothened inhibition produced more aggressive, vascular tumours (Rhim 2014). Hyaluronan degradation with pegvorhyaluronidase alfa raised the response rate (47% against 36%) but not survival (11.2 against 11.5 months) in 492 hyaluronan-high patients (Van Cutsem 2020).",
    sources: [link(SRC.olive2009), link(SRC.ozdemir2014), link(SRC.rhim2014), link(SRC.vanCutsem2020)] },
  { feature: "Fibroblast subtypes", finding: "Myofibroblastic CAFs (alpha-SMA high) sit next to tumour cells and lay down desmoplastic stroma; inflammatory CAFs sit further away and secrete IL-6 and other mediators (Ohlund 2017). Single-cell sequencing added antigen-presenting CAFs expressing MHC class II and CD74 without costimulatory molecules, able to activate CD4 T cells in a model (Elyada 2019).",
    implication: "Fibroblast plasticity anchors the reactive versus deserted sub-tumour microenvironments that track immunity, subtype and chemotherapy response (Grunwald 2021); the stroma is multi-faceted, which is why single-target stromal drugs failed (Ho 2020).",
    sources: [link(SRC.ohlund2017), link(SRC.elyada2019), link(SRC.grunwald2021), link(SRC.ho2020)] },
  { feature: "T-cell exclusion", finding: "In the autochthonous mouse model, tumour-specific CD8 T cells existed but anti-CTLA-4 and anti-PD-L1 did nothing; FAP-positive CAFs were the main source of CXCL12, which coated cancer cells and kept T cells out; blocking CXCR4 with AMD3100 let T cells in and synergised with anti-PD-L1 (Feig 2013). PDAC cells route MHC class I to lysosomes through NBR1-dependent autophagy, and autophagy inhibition restored surface MHC-I and synergised with dual checkpoint blockade in mice (Yamamoto 2020).",
    implication: "Immune suppression is built from the earliest stages by the oncogenic drivers, and single-agent immune modulators have proved clinically ineffective; multi-modal regimens that confer antigen specificity, enhance T-cell function and neutralise the suppressive microenvironment are the proposed route (Bear 2020).",
    sources: [link(SRC.feig2013), link(SRC.yamamoto2020), link(SRC.bear2020)] },
  { feature: "Checkpoint blockade outside mismatch repair deficiency", finding: "Ipilimumab: no RECIST response in 27 patients, one delayed regression (Royal 2010). Anti-PD-L1 (BMS-936559): 0 of 14 pancreatic patients responded in the 207-patient phase 1 (Brahmer 2012). Durvalumab with or without tremelimumab: response 3.1% and 0% among 65 previously treated metastatic patients, so the trial did not expand (O'Reilly 2019).",
    implication: "The only approved immunotherapy route is tumour-agnostic pembrolizumab for MSI-high or mismatch repair deficient disease, about 1% of cases (Hu 2018; Luchini 2021; Marabelle 2020). Long-term survivors are the exception that shows immunity can matter: tumours with both the highest neoantigen number and the most abundant CD8 infiltrates, and neoantigens of high quality including MUC16, stratified the longest survival, with immunoediting of those clones at metastasis (Balachandran 2017).",
    sources: [link(SRC.royal2010), link(SRC.brahmer2012), link(SRC.oreilly2019durva), link(SRC.hu2018ccr), link(SRC.luchini2021), link(SRC.marabelle2020), link(SRC.balachandran2017)] },
  { feature: "Immunogenic and repair-defective subgroups", finding: "The double-strand break repair and mismatch repair signature subtypes express more antitumour immunity genes (GZMA, PRF1) and more CTLA-4, PD-1 and IDO1, in step with their mutation and neoantigen load (Connor 2017); Bailey's immunogenic subtype carries upregulated immune networks including acquired immune suppression (Bailey 2016); KRAS wild-type tumours show more CD8 T cells, NK cells and myeloid dendritic cells and more MSI-high and TMB-high cases (Philip 2022).",
    implication: "These are the subgroups in which immunotherapy combinations are being tried; they are a minority and none has an approval beyond MSI-high.",
    sources: [link(SRC.connor2017), link(SRC.bailey2016), link(SRC.philip2022)] },
];

export const pancreaticMonitoringMarkers: Array<{ marker: string; use: string; limits: string; sources: Array<{ label: string; url: string }> }> = [
  { marker: "CA 19-9 (sialylated Lewis a)", use: "Pooled median sensitivity 79% and specificity 82% for diagnosis across 2,283 patients (Goonetilleke 2007). Pretreatment level is an independent prognostic factor: baseline at or above 59 times the upper limit of normal gave median survival 5.8 against 10.3 months among 247 randomised patients (Hess 2008). In prediagnostic PLCO sera from 175 future cases, levels rose exponentially from two years before diagnosis, reaching 60% sensitivity at 99% specificity within six months of diagnosis (Fahrmann 2021).",
    limits: "Lewis a-b- patients cannot make CA 19-9: FUT3-null (Lewis-negative) patients are about 10% of pancreatic cancer patients, with median baseline 2.4 against 496 U/mL, and a value of 7 U/mL or below is a practical surrogate for non-producer status (positive predictive value 95.1%) among 615 genotyped patients (Yeh 2026); Le a-b- patients failed to express CA 19-9 in tumour and serum while 88% of Lewis-positive patients had raised levels (Tempero 1987). Cholestasis raises it (Goonetilleke 2007). A 50% fall after two cycles, or at nadir, was not associated with longer survival after correcting for guarantee-time bias, so CA 19-9 response is not a valid surrogate endpoint for survival (Hess 2008).",
    sources: [link(SRC.goonetilleke2007), link(SRC.hess2008), link(SRC.fahrmann2021), link(SRC.yeh2026), link(SRC.tempero1987)] },
  { marker: "ctDNA (KRAS-mutant cell-free DNA)", use: "Detectable in 43% of localised disease at diagnosis, with recurrence found 6.5 months before CT after resection (Sausen 2015); 48% of 104 advanced patients, where detection meant overall survival 6.5 against 19.0 months and allele-fraction tertiles 18.9, 7.8 and 4.9 months (Pietrasz 2017); baseline ctDNA in metastatic disease gave a death hazard ratio of 2.8 among 194 patients, with exosome DNA adding predictive value (Bernard 2019). A CLIA digital-PCR KRAS assay detected ctDNA preoperatively in 49% of 59 resected patients and predicted recurrence with 90% sensitivity and 88% specificity, median lead time 84 days (Groot 2019); detection after resection gave a recurrence hazard ratio of 5.4 and 13 of 13 positive patients recurred despite adjuvant gemcitabine in 7 (Lee 2019). Concordance of plasma and tumour KRAS mutation exceeded 95% (Bernard 2019) and was 100% in 221 resectable patients (Cohen 2017).",
    limits: "Localised tumours shed little: plasma KRAS was found in only 30% of 221 resectable cancers, rising to 64% with four protein markers at 99.5% specificity (Cohen 2017); neoadjuvant chemotherapy lowers preoperative detection (21% against 69%; Groot 2019); KRAS-only assays are blind to the 6 to 12% of wild-type tumours; no pancreatic approval or guideline uses ctDNA (Lee 2019).",
    sources: [link(SRC.sausen2015), link(SRC.pietrasz2017), link(SRC.bernard2019), link(SRC.groot2019), link(SRC.lee2019), link(SRC.cohen2017)] },
];

export const pancreaticEarlyDetection: Array<{ programme: string; status: string; finding: string; sources: Array<{ label: string; url: string }> }> = [
  { programme: "CAPS (Cancer of the Pancreas Screening consortium)", status: "Research surveillance of high-risk individuals; CAPS5 outcomes published", finding: "354 high-risk individuals followed for a median 5.6 years: 24, 7%, progressed (14 cancers, 10 high-grade dysplasias), 1.6% a year; 9 of 10 cancers found in surveillance were resectable and 85% of those patients survived three years against 25% of the four symptomatic cancers outside surveillance (Canto 2018). CAPS5 enrolled 1,461, 48.5% with a susceptibility variant; 7 of 9 surveillance-detected cancers were stage I; across CAPS1 to 5 (1,731 patients) 57.9% of the 19 cancers found in surveillance were stage I, five-year survival 73.3%, median overall survival 9.8 against 1.5 years for cancers diagnosed outside surveillance (hazard ratio 0.13) (Dbouk 2022). The 2020 consensus: start at 50 or ten years before the youngest affected relative, annual EUS and MRI, ATM carriers with one affected first-degree relative eligible, all within research programmes (Goggins 2020).",
    sources: [link(SRC.canto2018), link(SRC.dbouk2022), link(SRC.goggins2020)] },
  { programme: "PRECEDE (Pancreatic Cancer Early Detection consortium)", status: "Research; international cohort of high-risk individuals under a PROBE biomarker design", finding: "Consortium recommendations for a more organised approach to early detection (Gonda 2021); imaging surveillance remains the foundation, cyst fluid and pancreatic juice add specificity, and radiomic, liquid biopsy, microbiome and multi-omic biomarkers are under discovery and validation, with precursor lesions still hard to see or grade non-invasively and biomarker thresholds unestablished (Worthington 2026).",
    sources: [link(SRC.gonda2021), link(SRC.worthington2026)] },
  { programme: "New-onset diabetes enrichment (ENDPAC)", status: "Research; independent prospective validation awaited", finding: "About 1% of people over 50 with new-onset diabetes are diagnosed with pancreatic cancer within three years; a score from weight change, glucose change and age at onset of 3 or more identified 78% of cases at 85% specificity in a 1,096-patient validation cohort, a 4.4-fold enrichment, and flagged 75% of discovery cases more than six months before diagnosis (Sharma 2018).",
    sources: [link(SRC.sharma2018)] },
  { programme: "Blood tests (CA 19-9 anchored panels, CancerSEEK, DETECT-A, Galleri)", status: "Research; no pancreatic screening test is approved or recommended for average-risk adults", finding: "CA 19-9 plus LRG1 and TIMP1 added 13.2% sensitivity at 99% specificity within a year of diagnosis (Fahrmann 2021). CancerSEEK detected eight cancer types in a median 70% of 1,005 non-metastatic patients at over 99% specificity, with pancreas in the 69 to 98% band (Cohen 2018). DETECT-A tested 10,006 women: 26 cancers found by blood, 1% had PET-CT for false positives and 0.22% a futile invasive procedure (Lennon 2020). The Galleri methylation test read 51.5% overall sensitivity, 16.8% at stage I, at 99.5% specificity in 4,077 CCGA3 participants (Klein 2021).",
    sources: [link(SRC.fahrmann2021), link(SRC.cohen2018), link(SRC.lennon2020), link(SRC.klein2021)] },
];

